// NOT reentrant (static buffers keep the 4 KB control-task stack safe);
// call from the control task only.
inline void infer(const float* obs_raw, float* act_out) {
    static float cur[256], nxt[256];
    for (int i = 0; i < OBS_DIM; ++i) {
        float v = (obs_raw[i] - OBS_MEAN[i]) / sqrtf(OBS_VAR[i] + OBS_EPS);
        if (v > OBS_CLIP) v = OBS_CLIP; else if (v < -OBS_CLIP) v = -OBS_CLIP;
        cur[i] = v;
    }
    int in_dim = OBS_DIM;
    for (int l = 0; l < N_LAYERS; ++l) {
        int out_dim = LAYER_OUT[l];
        const float* W = WEIGHTS[l]; const float* B = BIASES[l];
        for (int o = 0; o < out_dim; ++o) {
            float acc = B[o]; const float* wrow = W + o * in_dim;
            for (int j = 0; j < in_dim; ++j) acc += wrow[j] * cur[j];
            nxt[o] = (l < N_LAYERS - 1) ? tanhf(acc) : acc;
        }
        for (int o = 0; o < out_dim; ++o) cur[o] = nxt[o];
        in_dim = out_dim;
    }
    for (int o = 0; o < ACT_DIM; ++o) {
        float a = cur[o]; if (a > 1.f) a = 1.f; else if (a < -1.f) a = -1.f;
        act_out[o] = a;
    }
}

// Boot-time self-check: returns max |infer(TEST_OBS) - TEST_ACT| (expect < 1e-4).
inline float selfCheck() {
    float act[ACT_DIM];
    infer(TEST_OBS, act);
    float err = 0.f;
    for (int i = 0; i < ACT_DIM; ++i) {
        float d = fabsf(act[i] - TEST_ACT[i]);
        if (d > err) err = d;
    }
    return err;
}

